/** Step 2. RUN *SYSTEM/BUILDREORG[T1]: genera y compila el reorganizador, no reorganiza. */
@Component
@RequiredArgsConstructor
public class ConstruyeReorganizadorTasklet implements Tasklet {

    private final ReorgTarjetasProperties props;
    private final GeneradorReorganizador generador;   // adaptador del motor de BD destino

    @Override
    public RepeatStatus execute(StepContribution c, ChunkContext ctx) {
        ResultadoGeneracion r = generador.genera(props.descripcion(), props.estructuras(),
                                                 props.reorganizacion());
        ctx.getStepContext().getStepExecution().getJobExecution()
           .getExecutionContext().put("compiladoOk", r.compiladoOk());   // T1 IS COMPILEDOK
        return RepeatStatus.FINISHED;
    }
}

